SetColumns(0);SetNthreads(1);SetQuitOnError(true);SetMemoryLimit(8*10^9);Alarm(180);tt:=Cputime();root:="work/deg10/continuation_20261031b/M3N18/";AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");k:=GF(13);X:=MDX11(3,18,k);C:=Curve(X);FF:=FunctionField(C);F,mp:=AlgorithmicFunctionField(FF);assert Genus(F)eq 10;E:=EllipticCurve(X`_E);P:=E!X`_P;Q:=E!X`_Q;
function Units(E,P,Q)ai:=aInvariants(E);fs:=[ai[3],ai[1]^3-27*ai[3]];for j in[1..9]do for b in[0..2]do R:=j*Q+b*P;fs cat:=[R[1],R[2]];end for;R:=j*Q;S:=R+P;Append(~fs,R[1]-S[1]);end for;return fs;end function;
fs:=Units(E,P,Q);cs:=Cusps(X);sigs:=[[Valuation(f,c):f in fs]:c in cs];assert #sigs eq 24 and #Seqset(sigs)eq 24;rep:=eval Read(root cat"endomorphism_gluing/short_cusp_divisors.m");blocks:=[];
for i in[1..24]do j:=Index(sigs,rep[1][i]);assert j ne 0;Append(~blocks,Divisor(cs[j]));assert Degree(blocks[i])eq rep[2][i];end for;
dat:=eval Read(root cat"paired_merged_p13_degree5_data.m");PK:=PolynomialRing(k);K<z>:=ext<k|PK!dat[3]>;out:=[];
for i in[1..2]do row:=rep[3][i];id,coeff:=Explode(row);idx:=i eq 1 select 106 else 1202;qt:=[Evaluate(PK!v,z):v in dat[5][idx]];cp:=MDPlaceCommonZeros(X`_coordinates,qt);D:=Divisor(cp);assert Degree(D)eq 5;A:=&+[coeff[j]*blocks[j]:j in[1..24]];assert Degree(A)eq 5;h:=Dimension(RiemannRochSpace(A-D));assert h eq 1;hA:=Dimension(RiemannRochSpace(A));assert hA eq 1;Append(~out,[id,idx,h,hA]);print "M318_PARENT_NATIVE_SHORTCLASS13",id,idx,h,hA,Cputime(tt);end for;
Write(root cat"parent_native_shortclass13.m",Sprint(out):Overwrite:=true);print "D31B_M318_PARENT_NATIVE_SHORTCLASS13_COMPLETE",#out,Cputime(tt);quit;
